fix:
Add `app/robots.js` (dynamic, so it tracks siteUrl):
```js
import siteMetadata from '@/data/siteMetadata'
export default function robots() {
  const base = siteMetadata.siteUrl.replace(/\/$/, '')
  return {
    rules: [{
      userAgent: '*',
      allow: '/',
      disallow: ['/admin', '/member', '/api/', '/auth/', '/verify/', '/card-test-longname', '/_next/'],
    }],
    sitemap: `${base}/sitemap.xml`,
    host: base,
  }
}
```
Do NOT put it in public/robots.txt: .gitignore:19 `*.xml` does not catch .txt, but a static file cannot track the siteUrl fix and Next's app/robots.js is the supported route.

